import sys

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    n = int(input_data[0])
    greetings = []
    for i in range(n):
        greetings.append((input_data[i + 1], i + 1))

    greetings.sort(key=lambda x: len(x[0]))

    selected_indices = []
    selected_strings = set()

    for s, idx in greetings:
        is_substring = False
        for t in selected_strings:
            if s in t:
                is_substring = True
                break
        if not is_substring:
            is_superstring = False
            for t in selected_strings:
                if t in s:
                    is_superstring = True
                    break
            if not is_superstring:
                selected_strings.add(s)
                selected_indices.append(idx)

    print(len(selected_indices))
    print(" ".join(map(str, sorted(selected_indices))))

if __name__ == "__main__":
    main()
